import {state} from './state.js';
export function burst(x,y,color,count=18,power=3){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(.5+Math.random())*power;state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:25+Math.random()*25,max:50,size:1+Math.random()*3,color});}}
export function updateEffects(dt){for(let i=state.particles.length-1;i>=0;i--){const p=state.particles[i];p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.vx*=.985;p.vy*=.985;p.life-=dt*60;if(p.life<=0)state.particles.splice(i,1);}if(state.particles.length>500)state.particles.splice(0,state.particles.length-500);}
export function drawEffects(ctx){for(const p of state.particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;ctx.shadowBlur=0;}
